update public.programming_modules
set description='افهم كيف تُخزَّن البيانات، وكيف تتواصل صفحات الويب مع الخوادم، وابدأ أساسيات SQL وواجهات API.',
    updated_at=now()
where id='backend-foundations';
insert into public.programming_lessons(id,module_id,title,summary,content_md,duration_minutes,sort_order,published)
values
('backend-01-frontend-backend','backend-foundations','ما الفرق بين Frontend وBackend؟','افهم أجزاء التطبيق وكيف تتبادل الواجهة والخادم البيانات.',
E'## أجزاء التطبيق\n- Frontend: الجزء الذي يتعامل معه المستخدم في المتصفح.\n- Backend: منطق التطبيق الذي يعمل على الخادم.\n- Database: مكان منظم لحفظ البيانات واسترجاعها.\n\n## رحلة طلب بسيطة\n1. يضغط المستخدم زرًا في الصفحة.\n2. ترسل الواجهة طلبًا إلى الخادم.\n3. يتحقق الخادم من الطلب ويتعامل مع قاعدة البيانات عند الحاجة.\n4. يعيد الخادم نتيجة مناسبة.\n5. تعرض الواجهة النتيجة للمستخدم.\n\n## مثال توضيحي\nتطبيق مهام يحتاج إلى واجهة لعرض المهام، وخادم لمعالجة الإضافة والحذف، وقاعدة بيانات لحفظ المهام.\n\n## تدريب\nارسم مخططًا بسيطًا لتطبيق مكتبة إلكترونية، وحدد ما الذي ينتمي إلى الواجهة والخادم وقاعدة البيانات.',12,1,true),
('backend-02-database-tables','backend-foundations','مقدمة قواعد البيانات والجداول','تعرف على قاعدة البيانات والجدول والصف والعمود.',
E'## ما قاعدة البيانات؟\nهي نظام منظم لتخزين المعلومات والبحث فيها وتحديثها.\n\n## مفاهيم أساسية\n- Database: قاعدة تضم مجموعة من الجداول.\n- Table: جدول لموضوع محدد مثل الطلاب أو الكتب.\n- Row: سجل واحد داخل الجدول.\n- Column: خاصية مثل الاسم أو تاريخ الإنشاء.\n\n## مثال جدول كتب\n```text\nbooks\n+----+-------------------+--------+\n| id | title             | year   |\n+----+-------------------+--------+\n| 1  | Learning Python   | 2024   |\n| 2  | Web Basics        | 2025   |\n+----+-------------------+--------+\n```\n\n## تدريب\nصمم على الورق جدولًا للكتب يحتوي على رقم وعنوان ومؤلف وسنة نشر. اكتب ثلاثة سجلات تجريبية.',14,2,true),
('backend-03-sql-select','backend-foundations','أول استعلام SQL: SELECT','اقرأ البيانات من جدول باستخدام SELECT وWHERE وORDER BY.',
E'## قراءة كل السجلات\n```sql\nSELECT *\nFROM books;\n```\n\n## اختيار أعمدة محددة\n```sql\nSELECT title, year\nFROM books;\n```\n\n## التصفية والترتيب\n```sql\nSELECT title, year\nFROM books\nWHERE year >= 2024\nORDER BY year DESC;\n```\n\n## فهم الاستعلام\nSELECT يحدد الأعمدة، وFROM يحدد الجدول، وWHERE يضع شرطًا، وORDER BY يرتب النتائج.\n\n## تدريب\nاكتب استعلامًا يعرض أسماء الكتب المنشورة بعد سنة 2020، مرتبة من الأحدث إلى الأقدم.',15,3,true),
('backend-04-sql-insert-update-delete','backend-foundations','إضافة وتحديث وحذف البيانات','تعلم أوامر INSERT وUPDATE وDELETE مع فهم أهمية شرط التصفية.',
E'## إضافة سجل\n```sql\nINSERT INTO books (title, year)\nVALUES (''Web Design Basics'', 2025);\n```\n\n## تحديث سجل\n```sql\nUPDATE books\nSET year = 2026\nWHERE id = 2;\n```\n\n## حذف سجل\n```sql\nDELETE FROM books\nWHERE id = 3;\n```\n\n## انتبه\nقبل تنفيذ UPDATE أو DELETE تأكد من شرط WHERE. من دونه قد يتأثر عدد كبير من السجلات بدل السجل المقصود. تدرب دائمًا على بيانات تجريبية.\n\n## تدريب\nاكتب أوامر تضيف كتابًا، ثم تحدث سنة نشره، ثم تحذف سجلًا تجريبيًا باستخدام رقم محدد.',16,4,true),
('backend-05-primary-foreign-keys','backend-foundations','المفاتيح والعلاقات بين الجداول','افهم Primary Key وForeign Key وكيف ترتبط البيانات ببعضها.',
E'## المفتاح الأساسي Primary Key\nقيمة تميز كل سجل عن غيره، مثل رقم الطالب.\n\n## المفتاح الخارجي Foreign Key\nعمود يشير إلى سجل في جدول آخر، ويساعد على ربط البيانات.\n\n## مثال\n```sql\nCREATE TABLE authors (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL\n);\n\nCREATE TABLE books (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  author_id INTEGER REFERENCES authors(id)\n);\n```\n\n## لماذا العلاقات مهمة؟\nبدل تكرار بيانات المؤلف داخل كل كتاب، نخزن المؤلف مرة واحدة ونربط الكتب به.\n\n## تدريب\nصمم جدولين للطلاب والفصول، واجعل كل طالب مرتبطًا بفصل باستخدام مفتاح خارجي.',17,5,true),
('backend-06-http-api','backend-foundations','مقدمة HTTP وواجهات API','افهم الطلب والاستجابة وبعض أشهر طرق HTTP.',
E'## ما API؟\nواجهة API تحدد طريقة منظمة لطلب بيانات أو تنفيذ عملية من تطبيق آخر.\n\n## طرق HTTP شائعة\n- GET لقراءة البيانات.\n- POST لإرسال بيانات أو إنشاء سجل.\n- PATCH لتحديث جزء من سجل.\n- DELETE لحذف سجل وفق صلاحيات التطبيق.\n\n## مثال لمسارات API\n```text\nGET    /api/books\nGET    /api/books/12\nPOST   /api/books\nPATCH  /api/books/12\nDELETE /api/books/12\n```\n\n## رموز الاستجابة\n200 تعني نجاح الطلب، و201 إنشاء مورد، و400 طلب غير صالح، و401 يتطلب تسجيل الدخول، و403 لا توجد صلاحية، و404 غير موجود، و500 خطأ في الخادم.\n\n## تدريب\nاقترح مسارات API لتطبيق مهام، وحدد الطريقة المناسبة لعرض المهام وإضافة مهمة وتعديلها.',17,6,true),
('backend-07-fetch-json','backend-foundations','قراءة بيانات API باستخدام Fetch وJSON','أرسل طلب GET واقرأ الاستجابة وتحقق من الأخطاء.',
E'## طلب بيانات\n```javascript\nasync function loadBooks() {\n  try {\n    const response = await fetch("/api/books");\n    if (!response.ok) {\n      throw new Error("Request failed: " + response.status);\n    }\n    const books = await response.json();\n    console.log(books);\n  } catch (error) {\n    console.error("Could not load books", error);\n  }\n}\n\nloadBooks();\n```\n\n## ما JSON؟\nصيغة نصية شائعة لتبادل البيانات بين التطبيقات. تمثل القيم في صورة كائنات ومصفوفات ونصوص وأرقام وقيم منطقية.\n\n## تذكّر\nلا تفترض أن كل طلب ينجح. افحص response.ok وتعامل مع أخطاء الشبكة والاستجابة بطريقة مناسبة.\n\n## تدريب\nاكتب دالة async تجلب قائمة مهام من مسار تجريبي، ثم تعرض عدد المهام في console مع معالجة الخطأ.',18,7,true),
('backend-08-security-basics','backend-foundations','أساسيات أمان البيانات والصلاحيات','تعرف على التحقق من المدخلات وحماية الأسرار ومبدأ أقل صلاحية.',
E'## قواعد مهمة\n- لا تضع كلمات المرور أو مفاتيح الخادم السرية داخل كود الواجهة أو المستودع العام.\n- تحقق من البيانات على الخادم حتى لو كان هناك تحقق في المتصفح.\n- استخدم الاستعلامات المجهزة أو معاملات آمنة بدل دمج مدخل المستخدم داخل SQL كنص.\n- امنح كل مستخدم الصلاحيات التي يحتاجها فقط.\n- لا تعرض بيانات مستخدم لمستخدم آخر دون إذن.\n\n## مثال على استعلام مجهز\n```javascript\n// مثال توضيحي بأسلوب placeholders في مكتبة خادم\nconst result = await database.query(\n  "SELECT id, title FROM books WHERE author_id = ?",\n  [authorId]\n);\n```\n\n## المصادقة والتفويض\nAuthentication تسأل: من المستخدم؟ Authorization تسأل: ما الذي يُسمح لهذا المستخدم بفعله؟ وهما مفهومان مختلفان.\n\n## تدريب\nراجع تصميم تطبيق مهام، واكتب ثلاث قواعد تمنع المستخدم من رؤية مهام حساب آخر أو تعديلها.',20,8,true)
on conflict(id) do nothing;